<template>
  <b-container fluid class="py-3">
    <b-overlay :show="isLoading" rounded="sm" opacity="0.6">
      <b-row>
        <b-col lg="8" md="7">
          <b-card header-bg-variant="light" shadow="sm">
            <template #header>
              <h5 class="mb-0">
                <b-icon icon="building" class="mr-2"></b-icon>Informações da
                Instituição
              </h5>
            </template>

            <b-form @submit.prevent="updateCompanyDetails">
              <b-row>
                <b-col md="6">
                  <b-form-group
                    label="Nome da Empresa"
                    label-class="font-weight-bold small"
                  >
                    <b-form-input
                      v-model="form.companyName"
                      size="sm"
                      placeholder="Ex: Microcrédito Sucesso"
                      required
                    ></b-form-input>
                  </b-form-group>
                </b-col>
                <b-col md="6">
                  <b-form-group
                    label="E-mail Corporativo"
                    label-class="font-weight-bold small"
                  >
                    <b-form-input
                      v-model="form.companyEmail"
                      type="email"
                      size="sm"
                      placeholder="email@empresa.com"
                      required
                    ></b-form-input>
                  </b-form-group>
                </b-col>
              </b-row>

              <b-row>
                <b-col md="6">
                  <b-form-group
                    label="Telefone (12 dígitos)"
                    label-class="font-weight-bold small"
                  >
                    <b-form-input
                      v-model="form.companyPhone"
                      size="sm"
                      placeholder="258XXXXXXXXX"
                      required
                    ></b-form-input>
                  </b-form-group>
                </b-col>
                <b-col md="6">
                  <b-form-group
                    label="Gestor / Responsável"
                    label-class="font-weight-bold small"
                  >
                    <b-form-input
                      v-model="form.companyManager"
                      size="sm"
                      required
                    ></b-form-input>
                  </b-form-group>
                </b-col>
              </b-row>

              <b-row>
                <b-col md="6">
                  <b-form-group
                    label="Website"
                    label-class="font-weight-bold small"
                  >
                    <b-form-input
                      v-model="form.companyWebsite"
                      size="sm"
                      placeholder="https://..."
                    ></b-form-input>
                  </b-form-group>
                </b-col>
                <b-col md="6">
                  <b-form-group
                    label="NUIT"
                    label-class="font-weight-bold small"
                  >
                    <b-form-input
                      v-model="form.companyNuit"
                      size="sm"
                      placeholder="9 dígitos"
                      required
                    ></b-form-input>
                  </b-form-group>
                </b-col>
              </b-row>

              <hr />

              <b-row>
                <b-col md="12">
                  <b-form-group
                    label="Endereço Físico"
                    label-class="font-weight-bold small"
                  >
                    <b-form-textarea
                      v-model="form.companyAddress"
                      rows="2"
                      max-rows="4"
                      placeholder="Rua, Bairro, Cidade..."
                    ></b-form-textarea>
                  </b-form-group>
                </b-col>
              </b-row>

              <b-row class="align-items-end">
                <b-col md="4">
                  <b-form-group
                    label="Juros de Mora (%)"
                    label-class="font-weight-bold small"
                  >
                    <b-input-group append="%" size="sm">
                      <b-form-input
                        v-model.number="form.forfeit"
                        type="number"
                        step="0.01"
                      ></b-form-input>
                    </b-input-group>
                  </b-form-group>
                </b-col>
                <b-col md="4">
                  <b-form-group
                    label="Remetente SMS"
                    label-class="font-weight-bold small"
                  >
                    <b-form-input
                      v-model="form.smsSender"
                      size="sm"
                      maxlength="11"
                    ></b-form-input>
                  </b-form-group>
                </b-col>
                <b-col md="4" class="text-right">
                  <b-button
                    type="submit"
                    variant="success"
                    block
                    size="sm"
                    :disabled="isLoading"
                  >
                    <b-icon icon="check-circle" class="mr-1"></b-icon> Salvar
                    Alterações
                  </b-button>
                </b-col>
              </b-row>
            </b-form>
          </b-card>
        </b-col>

        <b-col lg="4" md="5">
          <b-card shadow="sm" class="text-center">
            <h6 class="font-weight-bold text-muted mb-3 small text-uppercase">
              Logotipo da Empresa
            </h6>

            <div class="logo-container mb-3 p-2 border rounded">
              <b-img
                :src="form.companyLogo || imagePlaceholder"
                fluid
                rounded
                style="max-height: 180px; object-fit: contain"
                alt="Logo Preview"
              ></b-img>
            </div>

            <b-progress
              v-if="uploadValue > 0"
              :value="uploadValue"
              max="100"
              show-progress
              animated
              class="mb-3"
            ></b-progress>

            <b-form-file
              placeholder="Escolher nova imagem..."
              drop-placeholder="Solte o arquivo aqui..."
              accept="image/*"
              size="sm"
              @change="onFileChange"
              class="mb-2"
            ></b-form-file>

            <b-button
              variant="outline-primary"
              size="sm"
              block
              :disabled="!selectedFile || uploadValue > 0"
              @click="onUploadFile"
            >
              <b-icon icon="cloud-upload" class="mr-1"></b-icon> Carregar Logo
            </b-button>
          </b-card>
        </b-col>
      </b-row>
    </b-overlay>
  </b-container>
</template>

<script>
import { mapGetters } from "vuex";
import axios from "axios";
import firebase from "firebase/app";
import "firebase/storage";
import logs from "@/utils/logs";

export default {
  name: "CompanyDetailsComponent",

  data: () => ({
    form: {
      companyName: "",
      companyEmail: "",
      companyWebsite: "",
      companyManager: "",
      smsSender: "",
      companyNuit: "",
      companyPhone: "",
      companyAddress: "",
      companyLogo: "",
      forfeit: 0,
    },
    selectedFile: null,
    uploadValue: 0,
    imagePlaceholder: "https://via.placeholder.com/250x250?text=LOGO+EMPRESA",
  }),

  computed: {
    ...mapGetters(["isLoading", "user", "company"]),
  },

  mounted() {
    this.initializeForm();
  },

  methods: {
    initializeForm() {
      // Cria uma cópia profunda para evitar mutação direta na store
      if (this.company) {
        this.form = JSON.parse(JSON.stringify(this.company));
      }
    },

    validate() {
      if (this.form.companyName.length < 3)
        return "O nome da empresa é muito curto.";
      if (this.form.companyPhone.toString().length < 9)
        return "Telefone inválido.";
      if (!this.form.companyEmail.includes("@")) return "E-mail inválido.";
      if (this.form.companyNuit.toString().length !== 9)
        return "O NUIT deve ter exatamente 9 dígitos.";
      return null;
    },

    async updateCompanyDetails() {
      const error = this.validate();
      if (error) {
        this.showToast("Validação", "warning", error);
        return;
      }

      try {
        this.$store.commit("LOADING_STATUS", true);
        const { data } = await axios.put(
          `/api/company/${this.company.id}`,
          this.form
        );

        if (data.success) {
          this.showToast("Sucesso!", "success", "Configurações atualizadas.");
          this.$store.dispatch(
            "addLog",
            logs(this.user, "Dados da empresa atualizados", "Configurações")
          );
          this.$store.dispatch("getCompanyDetails", this.company.id);
        } else {
          this.showToast("Erro!", "danger", data.message);
        }
      } catch (err) {
        this.showToast("Erro!", "danger", "Falha na conexão com o servidor.");
      } finally {
        this.$store.commit("LOADING_STATUS", false);
      }
    },

    onFileChange(e) {
      const file = e.target.files[0];
      if (file) {
        this.selectedFile = file;
        // Gera preview local
        this.form.companyLogo = URL.createObjectURL(file);
      }
    },

    async onUploadFile() {
      if (!this.selectedFile) return;

      const storageRef = firebase
        .storage()
        .ref(`logos/${Date.now()}_${this.selectedFile.name}`);
      const uploadTask = storageRef.put(this.selectedFile);

      uploadTask.on(
        "state_changed",
        (snapshot) => {
          this.uploadValue =
            (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
        },
        (error) => this.showToast("Erro Upload", "danger", error.message),
        async () => {
          this.uploadValue = 0;
          const url = await uploadTask.snapshot.ref.getDownloadURL();
          this.form.companyLogo = url;
          this.selectedFile = null;
          this.updateCompanyDetails(); // Salva os dados com a nova URL
        }
      );
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(msg, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 4000,
      });
    },
  },
};
</script>

<style scoped>
.logo-container {
  min-height: 200px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #f8f9fa;
}
.card {
  border: none;
  border-radius: 10px;
}
</style>
